  const startOnceRunning = async () => {
    while (!shuttingDown && !telegramService.getStatus().running) {
      try {
        await telegramService.start();
        return;
      } catch (error) {
        log("start failed:", errorText(error), `- retrying in ${SUPERVISOR_RETRY_MS / 1e3}s`);
        await waitFor(SUPERVISOR_RETRY_MS);
      }
    }
  };
  void startOnceRunning();
  const shutdown = () => {
    if (shuttingDown) return;
    shuttingDown = true;
    telegramService.stop();
    httpServer.close(() => process.exit(0));
    setTimeout(() => process.exit(0), 3e3).unref();
  };
